+static inline bool is_not_vm_bootstrap() {
+  return !is_vm_bootstrap();
+}
+
+#ifdef ASSERT
+static void assert_exclusivity() {
+  assert(is_vm_bootstrap() || JvmtiThreadState_lock->owned_by_self(), "invariant");
+}
