+static void destroy(JvmtiAgentList** list) {
+  assert(list != nullptr, "invariant");
+  if (*list != nullptr) {
+    for (int i = 0; i < (*list)->length(); ++i) {
+      delete (*list)->at(i);
+    }
+    delete* list;
+    *list = nullptr;
+  }
