-  MutexLocker lock(JvmtiThreadState_lock);
-  JvmtiAgent* const agent = find_vm_init_agent(env);
-  if (agent != nullptr) {
-    assert(agent->is_timing_unstarted(), "invariant");
-    agent->initialization_begin();
-  }
