-void JvmtiAgentSet::initialization_end(JvmtiAgent* agent) {
-  if (agent == nullptr) {
-    return;
-  }
-  MutexLocker lock(JvmtiThreadState_lock);
-  assert(agent->is_initializing(), "invariant");
-  agent->initialization_end();
-  if (agent->is_disposed()) {
