-
-static void append(JvmtiAgent* agent, JvmtiAgentList** list) {
-  assert(agent != nullptr, "invariant");
-  assert(list != nullptr, "invariant");
-  if (*list == nullptr) {
-    *list = new JvmtiAgentList();
-  }
-  (*list)->append(agent);
-}
