-void JvmtiAgentSet::startup_xrun() {
-  assert(_xrun_agent_list != nullptr, "invariant");
-  for (int i = 0; i < _xrun_agent_list->length(); ++i) {
-    JvmtiAgent* const agent = _xrun_agent_list->at(i);
-    assert(agent->is_xrun(), "invariant");
-    startup(agent);
-  }
